import{z as o,x as p,o as E,c as n,q as t,j as A,D as e,d as s,s as l,S as i}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"Let’s Verify Step by Step","description":"","frontmatter":{"title":"Let’s Verify Step by Step","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/verify-step.md","filePath":"llm/verify-step.md","lastUpdated":1791413859000}'),B={name:"llm/verify-step.md"};function d(M,a,h,m,R,P){const r=p("Mermaid");return E(),n("div",null,[a[2]||(a[2]=t('<h1 id="let-s-verify-step-by-step" tabindex="-1">Let’s Verify Step by Step <a class="header-anchor" href="#let-s-verify-step-by-step" aria-label="Permalink to &quot;Let’s Verify Step by Step&quot;">​</a></h1><div class="epigraph"><p>同一批候选越来越多时，过程验证器仍能把 MATH 准确率往上推，结果验证器先饱和；可靠的奖励模型，比再把生成器加大一档更值钱。</p><footer>—— Lightman 等，Let&#39;s Verify Step by Step，ICLR 2024</footer></div><p>论文标题里的 verify 是实验主轴：生成器采样许多完整解答，用奖励模型当验证器做 Best-of-N，比较过程监督与结果监督谁更能随 \\(N\\) 涨。PRM 怎么标、怎么训，见 <a href="/llm/lightman-prm">Process Reward Models Lightman</a>；搜索侧接口见 <a href="/llm/step-level-verify">逐步验证</a> 与 <a href="/llm/prm-guided-search">PRM 引导搜索</a>。本篇按原文写验证命题、主表数字、以及「生成与验证分离」这条方法论。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>即使当时最强的解题模型，MATH 上仍会在中间步骤写错。改进有两条预算：继续训生成器，或把算力花在「同一题多写几份、再挑」。多写之后必须有一个排序器。多数票不看过程，只看最终数字的众数；ORM 拟合终点对错；PRM 拟合逐步对错。直觉上 \\(N\\) 增大，覆盖上升，但「看起来像对的错解」也变多。若排序器吃这一类假阳性，Best-of-N 会先涨后平台。作者要量的就是这条饱和是不是监督类型的函数。</p><p>Uesato 等在更易的 GSM8K 上曾看到过程与结果反馈达到相近终点错误率、过程更省数据。换到 MATH、换到更强生成器、换到大规模人标之后，结论会不会翻？另外，人标贵，主动学习能不能让每一条标签更值？最后，把数据公开，让验证器研究不必从零标起。</p><h3 id="评测切片必须先说清" tabindex="-1">评测切片必须先说清 <a class="header-anchor" href="#评测切片必须先说清" aria-label="Permalink to &quot;评测切片必须先说清&quot;">​</a></h3><p>PRM800K 训练用了 4.5K 道 MATH 测试题的解答标签，主曲线因此只在剩下 500 题上画。后来社区把这 500 题叫 MATH-500。N 的最大值是每题最多 1860 个样本（1024 token 内未给出答案的丢弃，Best-of-N 逻辑对此做了修正）。比较的是验证器，不是把 PRM 拿去 RL 微调生成器——原文没有把 PRM 当在线奖励做 PPO 的主结果。</p><p><span class="marginnote">「过程监督显著优于结果监督」在这篇里的操作化定义是：同一生成器、同一候选池、换验证器，Best-of-N 曲线更高、更晚饱和。不是「过程 RL 一定优于结果 RL」。R1 后来的规则奖励是另一条故事。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>大规模生成器（GPT-4 级，经 MathMix 与 MATH 微调）为每题采样候选。三个排序器：</p><ul><li><strong>多数票</strong>：最终数字出现次数最多的赢。</li><li><strong>ORM</strong>：在每题 100 条均匀样本上按终点对错训练，给完整 \\((x,y)\\) 一个标量。</li><li><strong>PRM</strong>：PRM800K 逐步人标训练，轨迹分取逐步正类概率乘积。</li></ul><p>Best-of-1860 在 MATH-500 上：多数票 69.6%，ORM 72.4%，PRM <strong>78.2%</strong>。作者强调随 \\(N\\) 增大，PRM 与 ORM 的间隙加宽——多出来的候选里，「错步但终点像对」被 ORM 排前、被 PRM 压下。小规模实验用来拆两个混淆：训练集不可比、以及终点给分会奖到假阳性。他们还用大 PRM 给学生 RM 打伪标，做数据量消融；主动学习相对均匀标注约 \\(2.6\\times\\) 数据效率。</p><p><span class="marginnote">术语翻译：ORM（结果奖励模型）是只看最终答案打分的评委；PRM（过程奖励模型）是逐行批改步骤的评委；多数票则没有评委，只数哪个最终答案出现得最多。三者接的是同一个候选池，比的只是「挑」的眼力。</span></p><p>域外：把同一套验证器接到其它数学分布上，过程仍优于结果（公开叙述里有 Best-of-100 从约 63.8% 到 72.9% 一档的对照，精确数字以原文图为准）。这支持「PRM 学的是步骤合法性，不完全是 MATH 题型指纹」。</p>',15)),(E(),A(i,null,{default:e(()=>[l(r,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E9%A2%98%E7%9B%AE%22%5D%20--%3E%20GEN%5B%22%E7%94%9F%E6%88%90%E5%99%A8%E9%87%87%20N%20%E6%9D%A1%E5%AE%8C%E6%95%B4%E8%A7%A3%E7%AD%94%22%5D%0A%20%20GEN%20--%3E%20MV%5B%22%E5%A4%9A%E6%95%B0%E7%A5%A8%22%5D%0A%20%20GEN%20--%3E%20ORM%5B%22ORM%20%E7%BB%88%E7%82%B9%E5%88%86%22%5D%0A%20%20GEN%20--%3E%20PRM%5B%22PRM%20%E9%80%90%E6%AD%A5%E5%88%86%E5%86%8D%E5%BD%92%E7%BA%A6%22%5D%0A%20%20MV%20--%3E%20C1%5B%22%E9%80%89%E4%B8%80%E6%9D%A1%22%5D%0A%20%20ORM%20--%3E%20C2%5B%22%E9%80%89%E4%B8%80%E6%9D%A1%22%5D%0A%20%20PRM%20--%3E%20C3%5B%22%E9%80%89%E4%B8%80%E6%9D%A1%22%5D%0A%20%20C1%20--%3E%20E%5B%22MATH-500%20%E7%9C%9F%E5%80%BC%22%5D%0A%20%20C2%20--%3E%20E%0A%20%20C3%20--%3E%20E%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h3 id="验证器比生成器更值得加数据" tabindex="-1">验证器比生成器更值得加数据 <a class="header-anchor" href="#验证器比生成器更值得加数据" aria-label="Permalink to &quot;验证器比生成器更值得加数据&quot;">​</a></h3><p>人标预算固定时，把标签给 PRM、让生成器保持采样，比把同等人力投入再写示范解，更能拉高 <em>已有候选池</em> 的选中准确率。这是标题的工程读法：先能检验，再谈更会写。生成器仍必须能偶尔写出正确轨迹，否则 \\(N\\) 再大覆盖也是零。验证器不能发明预训练里没有的知识，只能在模型已经会采样到的模式里做筛选。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><h3 id="为何-orm-先饱和" tabindex="-1">为何 ORM 先饱和 <a class="header-anchor" href="#为何-orm-先饱和" aria-label="Permalink to &quot;为何 ORM 先饱和&quot;">​</a></h3><p>\\(N\\) 增大，正确轨迹的命中率按 \\(1-(1-p)^N\\) 升，同时「欺骗终点分类器」的样本数也升。ORM 的特征——格式、\\boxed{}、答案看起来像整数——在错解里同样可学。PRM 对局部错误敏感，覆盖收益更能体现为准确率。当 \\(N\\) 大到开始系统攻击 PRM 盲点，同样会饱和，只是平台更晚。原文没有声称过程分数随 \\(N\\) 单调至无穷。</p><p><span class="marginnote">数字实例：单条命中率 \\(p=0.1\\) 时，\\(N=30\\) 的至少命中一条的概率是 \\(1-0.9^{30}\\approx 96\\%\\)，\\(N=300\\) 时几乎必然覆盖。但「看起来像对的错解」也随 \\(N\\) 成比例堆积进来——覆盖是递减收益的指数式，假阳性是线性堆积，Best-of-N 曲线的形状就是这两条线的赛跑。</span></p><p><span class="marginnote">生成器与验证器必须有余量。同源、同初始化、同盲点时，多采样只是把同一类错换顺序写出来。Lightman 用独立人标的 PRM，就是在买余量。用生成器自己的逐步对数概率当验证，测的是流畅不是合法。</span></p><h3 id="假阳性是结果监督的结构性问题" tabindex="-1">假阳性是结果监督的结构性问题 <a class="header-anchor" href="#假阳性是结果监督的结构性问题" aria-label="Permalink to &quot;假阳性是结果监督的结构性问题&quot;">​</a></h3><p>最终数字对、中间符号错两次互相抵消，终点标签仍为正。ORM 被要求拟合这个标签，就会把抵消结构当正面特征。PRM 在第一处符号错误给负，整条乘积崩掉。这不是实现细节，是两种损失函数看见的随机变量不同。小规模里把终点假阳性 relabel 之后，ORM 会好些，但原文认为即使如此，过程路线在 MATH 上仍更强——难度和错误模式与 GSM8K 不同。</p>',9)),(E(),A(i,null,{default:e(()=>[l(r,{id:"mermaid-85",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E4%B8%80%E6%9D%A1%E8%A7%A3%3A%20%E7%AC%AC%203%20%E6%AD%A5%E7%AC%A6%E5%8F%B7%E5%87%BA%E9%94%99%3Cbr%2F%3E%E4%B8%A4%E6%AC%A1%E9%94%99%E8%AF%AF%E4%BA%92%E7%9B%B8%E6%8A%B5%E6%B6%88%2C%20%E7%BB%88%E7%82%B9%E7%A2%B0%E5%B7%A7%E5%AF%B9%22%5D%20--%3E%20Q%7B%22%E4%BA%A4%E7%BB%99%E5%93%AA%E7%A7%8D%E7%9B%91%E7%9D%A3%3F%22%7D%0A%20%20Q%20--%3E%7C%22ORM%3A%20%E7%BB%88%E7%82%B9%E6%A0%87%E7%AD%BE%22%7C%20POS%5B%22%E6%A0%87%E7%AD%BE%E4%B8%BA%E6%AD%A3%3Cbr%2F%3E%E6%8A%B5%E6%B6%88%E7%BB%93%E6%9E%84%E8%A2%AB%E5%AD%A6%E6%88%90%E6%AD%A3%E9%9D%A2%E7%89%B9%E5%BE%81%22%5D%0A%20%20Q%20--%3E%7C%22PRM%3A%20%E9%80%90%E6%AD%A5%E6%A0%87%E7%AD%BE%22%7C%20NEG%5B%22%E7%AC%AC%203%20%E6%AD%A5%E5%88%A4%E8%B4%9F%3Cbr%2F%3E%E9%80%90%E6%AD%A5%E6%AD%A3%E6%A6%82%E7%8E%87%E4%B9%98%E7%A7%AF%E5%B4%A9%E6%8E%89%22%5D%0A%20%20POS%20--%3E%20SAT%5B%22N%20%E8%B6%8A%E5%A4%A7%E6%AD%A4%E7%B1%BB%E6%A0%B7%E6%9C%AC%E8%B6%8A%E5%A4%9A%3Cbr%2F%3EORM%20%E6%8E%92%E5%BA%8F%E5%85%88%E9%A5%B1%E5%92%8C%22%5D%0A%20%20NEG%20--%3E%20LATE%5B%22%E9%94%99%E6%AD%A5%E8%A2%AB%E5%8E%8B%E4%B8%8B%3Cbr%2F%3EPRM%20%E5%B9%B3%E5%8F%B0%E6%9B%B4%E6%99%9A%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>主数字绑在一个极强生成器与 MATH-500、N=1860。小模型、小 N、开放域对话，曲线形状会变。验证器错误会被 Best-of-N 放大：过优化奖励模型是已知现象。原文几乎只做完整轨迹打分，不做生成中途剪枝；树搜索是后续工作对同一分数的在线用法。人标过程不可轻易换成「用终点回标中间步」而不改命题。</p><p>不要把 78.2% 写成「GPT-4 做 MATH 的 pass@1」。pass@1 低得多；78.2% 是验证器在 1860 份样本里挑出来的。服务上跑 N=1860 的代价是 decode，不是一张更好的表。产品若只能付 N=4，过程优势会缩小。</p><p><span class="marginnote">常见误区：容易把 78.2% 报成「模型自己的解题正确率」。类比：不是学生考了 78 分，而是监考老师从他 1860 份草稿里挑出最好的一份去交卷得了 78 分——学生的单次水平（pass@1）远低于此，且挑一遍的 decode 开销要记账。</span></p><p><span class="marginnote">论文同时释放 PRM800K，是为了让验证器研究可复现。复现曲线仍缺大规模生成器权重；社区用公开样本仓库里的 1860 路打分可以核对接力，不能核对自己从零采样是否同分布。</span></p><h3 id="何时不必上逐步验证" tabindex="-1">何时不必上逐步验证 <a class="header-anchor" href="#何时不必上逐步验证" aria-label="Permalink to &quot;何时不必上逐步验证&quot;">​</a></h3><p>单测或符号引擎能硬判终点，多数票或程序检查器更干净。N=1 的延迟敏感聊天，验证器没有候选可挑。任务没有稳定步骤边界，先不要用这篇的协议。需要改生成器本身而不是挑候选，应做 RL 或 SFT，验证曲线回答不了「策略是否更新」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>原文主结果：MATH-500 上 Best-of-1860，PRM 78.2%、ORM 72.4%、多数票 69.6%；间隙随 N 加宽。</li><li>命题是验证器类型，不是过程 RL；生成与验证分离。</li><li>主动学习提高人标效率；大 PRM 可给学生模型当自动标注。</li><li>ORM 饱和来自终点假阳性随 N 增多；PRM 对错步敏感，平台更晚。</li><li>78.2% 必须带生成器、N、评测切片一起引用。</li><li>出处：Lightman, Kosaraju, Burda, Edwards, Baker, Lee, Leike, Schulman, Sutskever, Cobbe，<em>Let&#39;s Verify Step by Step</em>，ICLR 2024，arXiv:2305.20050。</li></ul>',9))])}const c=o(B,[["render",d]]);export{D as __pageData,c as default};
